/**
 * Bundle Optimization Utilities
 * Implements code splitting, lazy loading, and tree shaking improvements
 */

import React, { lazy, Suspense, ComponentType } from 'react';

// Simple loading component to avoid circular dependencies
const SimpleLoader: React.FC = () => (
  <div className="flex items-center justify-center min-h-[200px]">
    <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></div>
  </div>
);

// Dynamic import wrapper with error handling
export function createLazyComponent<T extends ComponentType<any>>(
  importFunc: () => Promise<{ default: T }>,
  fallback?: React.ComponentType
) {
  const LazyComponent = lazy(importFunc);

  return function WrappedComponent(props: React.ComponentProps<T>) {
    const FallbackComponent = fallback || SimpleLoader;

    return (
      <Suspense fallback={<FallbackComponent />}>
        <LazyComponent {...props} />
      </Suspense>
    );
  };
}

// Preload utilities for better performance
export const preloadComponent = (importFunc: () => Promise<any>) => {
  // Start loading the component
  importFunc().catch(err => {
    console.warn('Failed to preload component:', err);
  });
};

// Route-based code splitting
export const LazyRoutes = {
