// Resource preloading for critical assets
export function preloadCriticalResources() {
  // Preload critical CSS
  const criticalCss = [
    '/src/index.css'
  ];

  criticalCss.forEach(href => {
    const link = document.createElement('link');
    link.rel = 'preload';
    link.as = 'style';
    link.href = href;
    document.head.appendChild(link);
  });

  // Preload critical fonts
  const criticalFonts = [
    'https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap'
  ];

  criticalFonts.forEach(href => {
    const link = document.createElement('link');
    link.rel = 'preload';
    link.as = 'style';
    link.href = href;
    link.crossOrigin = 'anonymous';
    document.head.appendChild(link);
  });
}

// Image optimization utilities
export function createOptimizedImage(
  src: string,
  alt: string,
  options: {
    width?: number;
    height?: number;
    loading?: 'lazy' | 'eager';
    className?: string;
  } = {}
) {
  const { width, height, loading = 'lazy', className = '' } = options;

  return {
    src,
    alt,
    width,
    height,
    loading,
    className,
    // Generate srcSet for responsive images
    srcSet: width ? [
      `${src}?w=${Math.round(width * 0.5)} ${Math.round(width * 0.5)}w`,
      `${src}?w=${width} ${width}w`,
      `${src}?w=${Math.round(width * 1.5)} ${Math.round(width * 1.5)}w`,
      `${src}?w=${Math.round(width * 2)} ${Math.round(width * 2)}w`
    ].join(', ') : undefined,
    sizes: width ? `(max-width: ${width}px) 100vw, ${width}px` : undefined
  };
}

