// Performance monitoring
export class PerformanceMonitor {
  private static instance: PerformanceMonitor;
  private metrics: Map<string, number> = new Map();

  static getInstance() {
    if (!PerformanceMonitor.instance) {
      PerformanceMonitor.instance = new PerformanceMonitor();
    }
    return PerformanceMonitor.instance;
  }

  startTiming(label: string) {
    this.metrics.set(label, performance.now());
  }

  endTiming(label: string): number {
    const startTime = this.metrics.get(label);
    if (!startTime) {
      console.warn(`No start time found for ${label}`);
      return 0;
    }

    const duration = performance.now() - startTime;
    this.metrics.delete(label);

    // Log slow operations in development
    if (import.meta.env.DEV && duration > 100) {
      console.warn(`Slow operation detected: ${label} took ${duration.toFixed(2)}ms`);
    }

    return duration;
  }

  measureComponentRender<T extends ComponentType<any>>(
    Component: T,
    name: string
  ): T {
    return function MeasuredComponent(props: React.ComponentProps<T>) {
      const monitor = PerformanceMonitor.getInstance();

      React.useEffect(() => {
        monitor.startTiming(`${name}-render`);
        return () => {
          monitor.endTiming(`${name}-render`);
        };
      });

      return React.createElement(Component, props);
    } as T;
  }

  getMetrics() {
    return {
      // Web Vitals
      cls: this.getCLS(),
      fid: this.getFID(),
      lcp: this.getLCP(),
      // Custom metrics
      bundleSize: this.getBundleSize(),
      memoryUsage: this.getMemoryUsage()
    };
  }

  private getCLS(): number {
    // Cumulative Layout Shift
    return new Promise((resolve) => {
      new PerformanceObserver((list) => {
        let cls = 0;
        for (const entry of list.getEntries()) {
          if (!(entry as any).hadRecentInput) {
            cls += (entry as any).value;
          }
        }
        resolve(cls);
      }).observe({ type: 'layout-shift', buffered: true });
    }) as any;
  }

  private getFID(): number {
    // First Input Delay
    return new Promise((resolve) => {
      new PerformanceObserver((list) => {
        for (const entry of list.getEntries()) {
          resolve((entry as any).processingStart - entry.startTime);
        }
      }).observe({ type: 'first-input', buffered: true });
    }) as any;
  }

  private getLCP(): number {
    // Largest Contentful Paint
    return new Promise((resolve) => {
      new PerformanceObserver((list) => {
        const entries = list.getEntries();
        const lastEntry = entries[entries.length - 1];
        resolve(lastEntry.startTime);
      }).observe({ type: 'largest-contentful-paint', buffered: true });
    }) as any;
  }

  private getBundleSize(): number {
    // Estimate bundle size from network resources
    const resources = performance.getEntriesByType('navigation') as PerformanceNavigationTiming[];
    return resources.reduce((total, resource) => total + (resource.transferSize || 0), 0);
  }

  private getMemoryUsage(): any {
    // Memory usage (Chrome only)
    return (performance as any).memory || {
      usedJSHeapSize: 0,
      totalJSHeapSize: 0,
      jsHeapSizeLimit: 0
    };
  }
}

// Initialize performance monitoring
export const performanceMonitor = PerformanceMonitor.getInstance();

// Bundle analyzer helper - simplified for development
export function analyzeBundleSize() {
  if (import.meta.env.DEV) {
    console.log('Bundle analysis available - use npm run build for detailed analysis');

    // Simple bundle size estimation using performance API
    const resources = performance.getEntriesByType('resource') as PerformanceResourceTiming[];
    const totalSize = resources.reduce((total, resource) => {
      return total + (resource.transferSize || 0);
    }, 0);

    console.log(`Estimated total bundle size: ${(totalSize / 1024).toFixed(2)} KB`);
  }
}

