      rgba(255, 255, 255, 0) 100%
    );
  }

  .animate-float-bounce {
    animation: floatBounce 8s ease-in-out infinite;
  }

  .animate-pulse-float {
    animation: pulseFloat 6s ease-in-out infinite;
  }

  .animate-pulse-width {
    animation: pulseWidth 2s ease-in-out infinite;
  }

  @keyframes pulseSlow {
    0%, 100% {
      opacity: 0.7;
    }
    50% {
      opacity: 0.3;
    }
  }

  @keyframes shimmer {
    0% {
      transform: translateX(-100%);
    }
    100% {
      transform: translateX(100%);
    }
  }

  @keyframes floatBounce {
    0%, 100% {
      transform: translateY(0) scale(1);
      opacity: 0.7;
    }
    25% {
      transform: translateY(-15px) scale(1.05);
      opacity: 0.9;
    }
    50% {
      transform: translateY(0) scale(1);
      opacity: 0.7;
    }
    75% {
      transform: translateY(8px) scale(0.95);
      opacity: 0.6;
    }
  }

  @keyframes pulseFloat {
    0%, 100% {
      transform: translateY(0) scale(1);
      opacity: 0.6;
    }
    50% {
      transform: translateY(-10px) scale(1.2);
      opacity: 0.9;
    }
  }

  @keyframes pulseWidth {
    0%, 100% {
      width: 86%;
    }
    50% {
      width: 88%;
    }
  }

  /* Print styles to preserve dark mode */
@media print {
