}

.shadow-3d-premium {
  box-shadow: 
    0 25px 55px rgba(0, 0, 0, 0.35),
    0 40px 100px rgba(0, 0, 0, 0.25),
    inset 0 1px 0 rgba(255, 255, 255, 0.1);
}

/* 3D Button Effects */
.btn-3d {
  position: relative;
  background: linear-gradient(45deg, #667eea, #764ba2);
  border: none;
  border-radius: 12px;
  box-shadow: 
    0 8px 20px rgba(102, 126, 234, 0.3),
    0 0 0 1px rgba(255, 255, 255, 0.1),
    inset 0 1px 0 rgba(255, 255, 255, 0.2);
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  transform: translateZ(0);
}

.btn-3d:hover {
  transform: translateY(-2px) translateZ(10px);
  box-shadow: 
    0 12px 35px rgba(102, 126, 234, 0.4),
    0 0 0 1px rgba(255, 255, 255, 0.2),
    inset 0 1px 0 rgba(255, 255, 255, 0.3);
}

.btn-3d:active {
  transform: translateY(0) translateZ(0);
  box-shadow: 
    0 4px 15px rgba(102, 126, 234, 0.3),
    0 0 0 1px rgba(255, 255, 255, 0.1),
    inset 0 1px 0 rgba(255, 255, 255, 0.2);
}

/* 3D Card Effects */
.card-3d {
  position: relative;
  background: rgba(255, 255, 255, 0.9);
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-radius: 16px;
  backdrop-filter: blur(10px);
  box-shadow: 
    0 15px 35px rgba(0, 0, 0, 0.1),
    0 5px 15px rgba(0, 0, 0, 0.05),
    inset 0 1px 0 rgba(255, 255, 255, 0.3);
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  transform: translateZ(0);
}

.card-3d:hover {
  transform: translateY(-5px) rotateX(5deg) rotateY(5deg);
  box-shadow: 
    0 25px 55px rgba(0, 0, 0, 0.15),
    0 10px 25px rgba(0, 0, 0, 0.1),
    inset 0 1px 0 rgba(255, 255, 255, 0.4);
}

.card-3d-dark {
  background: rgba(31, 41, 55, 0.9);
  border: 1px solid rgba(255, 255, 255, 0.1);
  box-shadow: 
    0 15px 35px rgba(0, 0, 0, 0.3),
    0 5px 15px rgba(0, 0, 0, 0.2),
    inset 0 1px 0 rgba(255, 255, 255, 0.1);
}

.card-3d-dark:hover {
  transform: translateY(-5px) rotateX(5deg) rotateY(5deg);
  box-shadow: 
    0 25px 55px rgba(0, 0, 0, 0.4),
    0 10px 25px rgba(0, 0, 0, 0.3),
    inset 0 1px 0 rgba(255, 255, 255, 0.2);
}

/* 3D Text Effects */
.text-3d {
  text-shadow: 
    0 2px 4px rgba(0, 0, 0, 0.3),
    0 4px 8px rgba(0, 0, 0, 0.2),
    0 8px 16px rgba(0, 0, 0, 0.1);
}

.text-3d-premium {
  text-shadow: 
    0 3px 6px rgba(0, 0, 0, 0.4),
    0 6px 12px rgba(0, 0, 0, 0.3),
    0 12px 24px rgba(0, 0, 0, 0.2);
}

.text-3d-glow {
  text-shadow: 
    0 0 10px rgba(255, 255, 255, 0.5),
    0 0 20px rgba(255, 255, 255, 0.3),
    0 0 30px rgba(255, 255, 255, 0.2),
    0 2px 4px rgba(0, 0, 0, 0.3);
}

/* 3D Gradient Backgrounds */
.bg-3d-gradient {
  background: linear-gradient(
    135deg,
    rgba(99, 102, 241, 0.9) 0%,
    rgba(139, 69, 197, 0.9) 35%,
    rgba(59, 130, 246, 0.9) 70%,
    rgba(16, 185, 129, 0.9) 100%
  );
  position: relative;
}

.bg-3d-gradient::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: linear-gradient(
    45deg,
    transparent 30%,
    rgba(255, 255, 255, 0.1) 50%,
    transparent 70%
  );
  animation: shimmer 3s infinite;
}

@keyframes shimmer {
  0% { transform: translateX(-100%) skewX(-15deg); }
  100% { transform: translateX(200%) skewX(-15deg); }
}

/* 3D Floating Animation */
.float-3d {
  animation: float3d 6s ease-in-out infinite;
}

@keyframes float3d {
  0%, 100% { 
    transform: translateY(0px) rotateX(0deg); 
  }
  50% { 
    transform: translateY(-20px) rotateX(10deg); 
  }
}

/* 3D Pulse Animation */
.pulse-3d {
  animation: pulse3d 2s ease-in-out infinite;
}

@keyframes pulse3d {
  0%, 100% { 
    transform: scale(1) translateZ(0); 
    box-shadow: 0 0 0 0 rgba(59, 130, 246, 0.7);
  }
  50% { 
    transform: scale(1.05) translateZ(5px); 
    box-shadow: 0 0 0 10px rgba(59, 130, 246, 0);
  }
}

/* 3D Rotate Animation */
.rotate-3d {
  animation: rotate3d 10s linear infinite;
}

@keyframes rotate3d {
  0% { transform: rotateY(0deg) rotateX(0deg); }
  25% { transform: rotateY(90deg) rotateX(5deg); }
  50% { transform: rotateY(180deg) rotateX(0deg); }
  75% { transform: rotateY(270deg) rotateX(-5deg); }
  100% { transform: rotateY(360deg) rotateX(0deg); }
}

/* 3D Depth Effects */
.depth-1 { transform: translateZ(10px); }
.depth-2 { transform: translateZ(20px); }
.depth-3 { transform: translateZ(30px); }
.depth-4 { transform: translateZ(40px); }
.depth-5 { transform: translateZ(50px); }

/* 3D Hover Effects */
.hover-lift-3d {
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

.hover-lift-3d:hover {
  transform: translateY(-8px) translateZ(15px) rotateX(5deg);
  box-shadow: 
    0 20px 40px rgba(0, 0, 0, 0.2),
    0 10px 20px rgba(0, 0, 0, 0.1);
}

.hover-tilt-3d {
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

.hover-tilt-3d:hover {
  transform: rotateX(10deg) rotateY(10deg) translateZ(10px);
}

/* 3D Glass Effect */
.glass-3d {
  background: rgba(255, 255, 255, 0.1);
  backdrop-filter: blur(10px);
  border: 1px solid rgba(255, 255, 255, 0.2);
  box-shadow: 
    0 8px 32px rgba(0, 0, 0, 0.1),
    inset 0 1px 0 rgba(255, 255, 255, 0.2);
}

.glass-3d-dark {
  background: rgba(0, 0, 0, 0.2);
  backdrop-filter: blur(10px);
  border: 1px solid rgba(255, 255, 255, 0.1);
  box-shadow: 
    0 8px 32px rgba(0, 0, 0, 0.3),
    inset 0 1px 0 rgba(255, 255, 255, 0.1);
}

/* 3D Glow Effects */
.glow-3d {
  box-shadow: 
    0 0 20px rgba(59, 130, 246, 0.3),
    0 0 40px rgba(59, 130, 246, 0.2),
    0 0 80px rgba(59, 130, 246, 0.1);
}

.glow-3d-premium {
  box-shadow: 
    0 0 30px rgba(236, 72, 153, 0.4),
    0 0 60px rgba(236, 72, 153, 0.3),
    0 0 120px rgba(236, 72, 153, 0.2);
}

/* 3D Border Effects */
.border-3d {
  border: 2px solid transparent;
  background: linear-gradient(45deg, #667eea, #764ba2) border-box;
  border-radius: 12px;
  position: relative;
}

.border-3d::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  border-radius: 10px;
  background: linear-gradient(45deg, transparent, rgba(255, 255, 255, 0.1), transparent);
  z-index: -1;
}

/* Responsive 3D Effects */
@media (max-width: 768px) {
  .card-3d:hover {
    transform: translateY(-3px) rotateX(2deg) rotateY(2deg);
  }

  .hover-lift-3d:hover {
    transform: translateY(-4px) translateZ(8px) rotateX(2deg);
  }

  .perspective-1000 {
    perspective: 500px;
  }
}

/* Accessibility - Reduce motion for users who prefer it */
@media (prefers-reduced-motion: reduce) {
  .float-3d,
  .pulse-3d,
  .rotate-3d {
    animation: none;
  }

  .card-3d:hover,
  .hover-lift-3d:hover,
  .hover-tilt-3d:hover {
    transform: none;
  }
}

