src/components/pdf/StablePdfCanvas.tsx.content:
import { useEffect, useRef, useState, forwardRef, useImperativeHandle } from 'react';

interface StablePdfCanvasProps {
  width?: number | string;
  height?: number | string;
  className?: string;
  onCanvasReady?: (canvas: HTMLCanvasElement, context: CanvasRenderingContext2D) => void;
  onCanvasError?: (error: Error) => void;
}

/**
 * A canvas component specifically for PDF rendering that handles context errors
 * forwards ref to the underlying HTMLCanvasElement
 */
const StablePdfCanvas = forwardRef<HTMLCanvasElement, StablePdfCanvasProps>(
  ({ width, height, className, onCanvasReady, onCanvasError }, ref) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const [error, setError] = useState<string | null>(null);

    // Expose canvas element via ref
    useImperativeHandle(ref, () => canvasRef.current!);

    // Try to initialize the canvas and get its context when it's mounted
    useEffect(() => {
      const canvas = canvasRef.current;
      if (!canvas) return;

      try {
        // Try different context configurations to maximize compatibility
        let context: CanvasRenderingContext2D | null = null;

        // Try first with standard options
        context = canvas.getContext('2d');

        // If that fails, try with explicit options
        if (!context) {
          context = canvas.getContext('2d', { alpha: false });
        }

        // If that still fails, try with different options
        if (!context) {
          context = canvas.getContext('2d', { alpha: true });
        }

        if (!context) {
          throw new Error('Cannot get 2D canvas context after multiple attempts');
        }

        // Test the context with a simple draw operation
        try {
          context.fillStyle = 'rgba(0,0,0,0.01)';
          context.fillRect(0, 0, 1, 1);
          context.clearRect(0, 0, 1, 1);
        } catch (drawError) {
          throw new Error(`Canvas context exists but drawing failed: ${
            drawError instanceof Error ? drawError.message : 'Unknown error'
          }`);
        }

        // Canvas is ready with a working context
        setError(null);

        // Notify parent
        onCanvasReady?.(canvas, context);
      } catch (err) {
        console.error('Canvas initialization error:', err);
        setError(err instanceof Error ? err.message : 'Unknown canvas error');

        onCanvasError?.(err instanceof Error ? err : new Error('Unknown canvas error'));
      }
    }, [onCanvasReady, onCanvasError]);

    // Render the canvas with optional error message
    return (
      <>
      <canvas
        ref={canvasRef}
        className={`${className ?? ''} pdf-canvas`}
        width={typeof width === 'number' ? width : undefined}
        height={typeof height === 'number' ? height : undefined}
        data-testid="pdf-canvas"
      />
     {error && (
        <div className="canvas-error">
           <p>Canvas error: {error}</p>
           <p>Please try a different browser or update your current browser.</p>
         </div>
     )}
   </>
   );
});

StablePdfCanvas.displayName = 'StablePdfCanvas';
export default StablePdfCanvas;

supabase/functions/create-razorpay-order.content:
// Supabase Edge Function for creating a Razorpay order
import { serve } from 'https://deno.land/std@0.131.0/http/server.ts';
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2.7.1';

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

serve(async (req) => {
  // Handle CORS preflight requests
  if (req.method === 'OPTIONS') {
    return new Response(null, {
      status: 204,
      headers: corsHeaders
    });
  }

  try {
    const { planId, amount, currency, userId } = await req.json();

    // Validate required parameters
    if (!planId || !amount || !currency || !userId) {
      return new Response(JSON.stringify({
        error: 'Missing required parameters'
      }), {
        status: 400,
        headers: { ...corsHeaders, 'Content-Type': 'application/json' }
      });
    }

    // Initialize Razorpay
    const razorpayKeyId = Deno.env.get('RAZORPAY_KEY_ID');
    const razorpayKeySecret = Deno.env.get('RAZORPAY_KEY_SECRET');

    if (!razorpayKeyId || !razorpayKeySecret) {
      return new Response(JSON.stringify({
        error: 'Razorpay API keys not configured'
      }), {
        status: 500,
        headers: { ...corsHeaders, 'Content-Type': 'application/json' }
      });
    }

    // Create a receipt ID
    const receiptId = `order_rcptid_${userId}_${Date.now()}`;

    // Create the order with Razorpay API
    const response = await fetch('https://api.razorpay.com/v1/orders', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': 'Basic ' + btoa(`${razorpayKeyId}:${razorpayKeySecret}`)
      },
      body: JSON.stringify({
        amount: amount,
        currency: currency,
        receipt: receiptId,
        notes: {
          planId: planId,
          userId: userId
        }
      })
    });

    const data = await response.json();

    if (!response.ok) {
      return new Response(JSON.stringify({
        error: 'Failed to create Razorpay order',
        details: data
      }), {
        status: response.status,
        headers: { ...corsHeaders, 'Content-Type': 'application/json' }
      });
    }

    // Store the order in Supabase (optional but recommended for record keeping)
    const supabaseUrl = Deno.env.get('SUPABASE_URL');
    const supabaseServiceKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY');

    if (supabaseUrl && supabaseServiceKey) {
      const supabase = createClient(supabaseUrl, supabaseServiceKey);

      await supabase.from('payment_orders').insert({
        order_id: data.id,
        user_id: userId,
        plan_id: planId,
        amount: amount,
        currency: currency,
        status: data.status,
        created_at: new Date().toISOString()
      });
    }

    return new Response(JSON.stringify(data), {
      status: 200,
      headers: { ...corsHeaders, 'Content-Type': 'application/json' }
    });

  } catch (error) {
    return new Response(JSON.stringify({
      error: error.message
    }), {
      status: 500,
      headers: { ...corsHeaders, 'Content-Type': 'application/json' }
    });
  }
});

vite.config.ts.content:
import { defineConfig, loadEnv } from 'vite';
import react from '@vitejs/plugin-react';
import { fileURLToPath } from 'url';
import { dirname, resolve } from 'path';
import fs from 'fs';
import path from 'path';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

// https://vitejs.dev/config/
export default defineConfig(({ mode }) => {
  // Load environment variables from .env files
  const env = loadEnv(mode, process.cwd(), '');

  // Ensure PDF worker directory exists in public
  const pdfWorkerDir = resolve(__dirname, 'public', 'pdf-worker');
  if (!fs.existsSync(pdfWorkerDir)) {
    fs.mkdirSync(pdfWorkerDir, { recursive: true });
  }

  return {
    base: '/',
    plugins: [
      react(),
      // Custom plugin to fix MIME types and reduce header size
      {
        name: 'mime-fix',
        configureServer(server) {
          server.middlewares.use((req, res, next) => {
            const url = req.url || '';

            // Clear potentially large headers to prevent 431 error
            delete req.headers['x-forwarded-for'];
            delete req.headers['x-real-ip'];

            // Handle CSS files specifically
            if (url.endsWith('.css') || url.includes('.css')) {
              res.setHeader('Content-Type', 'text/css');
              res.setHeader('Cache-Control', 'public, max-age=3600');
            } 
            // Handle JavaScript files
            else if (url.endsWith('.js') || url.endsWith('.mjs') || url.includes('.js') || url.includes('.mjs')) {
              res.setHeader('Content-Type', 'application/javascript');
              res.setHeader('Cache-Control', 'public, max-age=3600');
            }
            // Handle assets folder specifically
            else if (url.startsWith('/assets/')) {
              if (url.includes('.css')) {
                res.setHeader('Content-Type', 'text/css');
                res.setHeader('Cache-Control', 'public, max-age=31536000, immutable');
              } else if (url.includes('.js') || url.includes('.mjs')) {
                res.setHeader('Content-Type', 'application/javascript');
                res.setHeader('Cache-Control', 'public, max-age=31536000, immutable');
              }
            }

            next();
          });
        }
      }
    ],
    optimizeDeps: {
      include: [
        'react',
        'react-dom',
        'react/jsx-runtime',
        '@radix-ui/react-tabs',
        '@supabase/supabase-js',
        'clsx',
        'tailwind-merge'
      ],
      esbuildOptions: {
        target: 'esnext'
      }
    },
    resolve: {
      alias: {
        '@': path.resolve(__dirname, './src'),
        // Force ALL React imports to use the exact same instance
        'react': path.resolve(__dirname, './node_modules/react'),
        'react-dom': path.resolve(__dirname, './node_modules/react-dom'),
        'react/jsx-runtime': path.resolve(__dirname, './node_modules/react/jsx-runtime')
      },
      dedupe: ['react', 'react-dom', 'react/jsx-runtime'],
      conditions: ['import', 'module', 'browser', 'default']
    },
    build: {
      commonjsOptions: {
        include: [/node_modules/],
        transformMixedEsModules: true
      },
      modulePreload: {
        polyfill: true
      },
      rollupOptions: {
        input: {
          main: resolve(__dirname, 'index.html'),
        },
        output: {
          manualChunks: (id) => {
            // React core - MUST be FIRST and use EXACT path matching
            // Only match node_modules/react/ and node_modules/react-dom/ exactly
            if (id.includes('node_modules/react/') || id.includes('node_modules/react-dom/')) {
              return 'react-vendor';
            }

            // PDF.js - Large PDF processing library
            if (id.includes('pdfjs-dist')) {
              return 'pdfjs';
            }

            // Chart libraries - Heavy visualization dependencies
            if (id.includes('chart.js') || id.includes('react-chartjs-2') || id.includes('recharts')) {
              return 'charts';
            }

            // UI component libraries - Large UI dependencies (depends on React)
            // CRITICAL: lucide-react MUST be in a React-dependent chunk
            if (id.includes('@radix-ui') || id.includes('framer-motion') || id.includes('lucide-react')) {
              return 'ui-components';
            }

            // Table and virtualization - Heavy data handling
            if (id.includes('@tanstack/react-table') || id.includes('react-virtualized') || id.includes('react-window')) {
              return 'data-tables';
            }

            // Authentication and API - Supabase and related (depends on React)
            if (id.includes('@supabase') || id.includes('@tanstack/react-query') || id.includes('axios')) {
              return 'api-auth';
            }

            // Form handling and validation
            if (id.includes('react-hook-form') || id.includes('zod') || id.includes('react-dropzone')) {
              return 'forms';
            }

            // Routing - React Router and related (depends on React)
            // CRITICAL: react-helmet-async uses React.createContext at module level
            if (id.includes('react-router-dom') || id.includes('react-helmet-async')) {
              return 'routing';
            }

            // Utilities REMOVED - let Vite handle lucide-react automatically
            // This prevents utilities from loading before React

            // Large individual page components for lazy loading
            if (id.includes('/pages/') && (
              id.includes('AnalyticsPage') || 
              id.includes('ATSOptimizationPage') || 
              id.includes('ResumeAnalyzerPage') ||
              id.includes('ResultsPage') ||
              id.includes('ProfilePage')
            )) {
              return 'heavy-pages';
            }

            // All other node_modules as vendor
            if (id.includes('node_modules')) {
              return 'vendor';
            }
          }
        }
      },
      // Increase chunk size warning limit to avoid warnings for intentionally large chunks
      chunkSizeWarningLimit: 600,
      outDir: 'frontend-build',
    },
    css: {
      postcss: './postcss.config.js',
    },
    server: {
      fs: {
        allow: ['..'],
      },
      headers: {
        'Cross-Origin-Embedder-Policy': 'require-corp',
        'Cross-Origin-Opener-Policy': 'same-origin'
      },
      middlewareMode: false,
      hmr: {
        overlay: true
      },
      // Replit environment configuration
      host: '0.0.0.0',
      port: 5000,
      strictPort: false,
      allowedHosts: true
    },
    define: {
      'process.env.NODE_ENV': JSON.stringify(mode === 'production' ? 'production' : mode),
      __API_CONFIG__: {
        GROQ_API_KEY: JSON.stringify(env.VITE_GROQ_API_KEY),
        TOGETHER_API_KEY: JSON.stringify(env.VITE_TOGETHER_API_KEY),
        SUPABASE_URL: JSON.stringify(env.VITE_SUPABASE_URL),
        SUPABASE_ANON_KEY: JSON.stringify(env.VITE_SUPABASE_ANON_KEY),
        OPENAI_API_KEY: JSON.stringify(env.VITE_OPENAI_API_KEY),
        PINECONE_API_KEY: JSON.stringify(env.VITE_PINECONE_API_KEY),
        PINECONE_ENVIRONMENT: JSON.stringify(env.VITE_PINECONE_ENVIRONMENT),
      }
    },
  };
});

backend/src/services/analyticsService.ts.content:
import { supabase } from '../config/database.js';
import { logger } from '../utils/logger.js';
import { ResumeAnalysisResult } from './aiAnalysisService.js';

export interface AnalysisData {
  resumeText: string;
  jobRole: string;
  analysisType: string;
  result: ResumeAnalysisResult;
  fileName: string;
  fileSize: number;
}

export interface SavedAnalysis {
  id: string;
  userId: string;
  jobRole: string;
  analysisType: string;
  fileName: string;
  fileSize: number;
  atsScore: number;
  overallScore: number;
  result: ResumeAnalysisResult;
  createdAt: string;
  updatedAt: string;
}

/**
 * Save resume analysis to database
 */
export const saveAnalysisToDatabase = async (
  userId: string,
  analysisData: AnalysisData
): Promise<SavedAnalysis> => {
  try {
    logger.debug(`Saving analysis to database for user: ${userId}`);

    const { data, error } = await supabase
      .from('resume_analyses')
      .insert({
        user_id: userId,
        job_role: analysisData.jobRole,
        analysis_type: analysisData.analysisType,
        file_name: analysisData.fileName,
        file_size: analysisData.fileSize,
        resume_text: analysisData.resumeText,
        ats_score: analysisData.result.atsScore,
        overall_score: analysisData.result.overallScore,
        result: analysisData.result,
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      })
      .select()
      .single();

    if (error) {
      logger.error('Database save error:', error);
      throw new Error('Failed to save analysis to database');
    }

    // Update user analytics
    await updateUserAnalytics(userId, analysisData.result);

    logger.info(`Analysis saved successfully with ID: ${data.id}`);

    return {
      id: data.id,
      userId: data.user_id,
      jobRole: data.job_role,
      analysisType: data.analysis_type,
      fileName: data.file_name,
      fileSize: data.file_size,
      atsScore: data.ats_score,
      overallScore: data.overall_score,
      result: data.result,
      createdAt: data.created_at,
      updatedAt: data.updated_at,
    };

  } catch (error) {
    logger.error('Error saving analysis to database:', error);
    throw error;
  }
};

/**
 * Update user analytics with new analysis data
 */
export const updateUserAnalytics = async (
  userId: string,
  analysisResult: ResumeAnalysisResult
): Promise<void> => {
  try {
    // Get current analytics
    const { data: currentAnalytics } = await supabase
      .from('user_analytics')
      .select('*')
      .eq('user_id', userId)
      .single();

    const now = new Date().toISOString();
    const previousAtsScore = currentAnalytics?.ats_score || 0;

    if (currentAnalytics) {
      // Update existing analytics
      const { error } = await supabase
        .from('user_analytics')
        .update({
          ats_score: analysisResult.atsScore,
          previous_ats_score: previousAtsScore,
          overall_score: analysisResult.overallScore,
          skills_matched: analysisResult.skillsAnalysis.presentSkills.length,
          total_skills: analysisResult.skillsAnalysis.presentSkills.length + analysisResult.skillsAnalysis.missingSkills.length,
          readability_score: analysisResult.estimatedReading.difficulty === 'easy' ? 90 : 
                           analysisResult.estimatedReading.difficulty === 'medium' ? 70 : 50,
          keyword_density: analysisResult.keywordAnalysis.density,
          total_analyses: (currentAnalytics.total_analyses || 0) + 1,
          last_analysis_date: now,
          updated_at: now,
        })
        .eq('user_id', userId);

      if (error) {
        logger.error('Error updating user analytics:', error);
      }
    } else {
      // Create new analytics record
      const { error } = await supabase
        .from('user_analytics')
        .insert({
          user_id: userId,
          ats_score: analysisResult.atsScore,
          previous_ats_score: 0,
          overall_score: analysisResult.overallScore,
          skills_matched: analysisResult.skillsAnalysis.presentSkills.length,
          total_skills: analysisResult.skillsAnalysis.presentSkills.length + analysisResult.skillsAnalysis.missingSkills.length,
          readability_score: analysisResult.estimatedReading.difficulty === 'easy' ? 90 : 
                           analysisResult.estimatedReading.difficulty === 'medium' ? 70 : 50,
          keyword_density: analysisResult.keywordAnalysis.density,
          total_analyses: 1,
          last_analysis_date: now,
          created_at: now,
          updated_at: now,
        });

      if (error) {
        logger.error('Error creating user analytics:', error);
      }
    }

    // Add trend data
    await addAnalyticsTrend(userId, analysisResult);

  } catch (error) {
    logger.error('Error updating user analytics:', error);
    // Don't throw error as this is not critical for the main flow
  }
};

/**
 * Add analytics trend data
 */
export const addAnalyticsTrend = async (
  userId: string,
  analysisResult: ResumeAnalysisResult
): Promise<void> => {
  try {
    const { error } = await supabase
      .from('analytics_trends')
      .insert({
        user_id: userId,
        ats_score: analysisResult.atsScore,
        overall_score: analysisResult.overallScore,
        readability_score: analysisResult.estimatedReading.difficulty === 'easy' ? 90 : 
                         analysisResult.estimatedReading.difficulty === 'medium' ? 70 : 50,
        keyword_density: analysisResult.keywordAnalysis.density,
        skills_match: analysisResult.skillsAnalysis.skillsMatch,
        timestamp: new Date().toISOString(),
      });

    if (error) {
      logger.error('Error adding analytics trend:', error);
    }

  } catch (error) {
    logger.error('Error adding analytics trend:', error);
  }
};

/**
 * Get user analytics dashboard data
 */
export const getUserAnalytics = async (userId: string) => {
  try {
    // Get current analytics
    const { data: analytics, error: analyticsError } = await supabase
      .from('user_analytics')
      .select('*')
      .eq('user_id', userId)
      .single();

    if (analyticsError && analyticsError.code !== 'PGRST116') {
      throw analyticsError;
    }

    // Get trend data (last 30 data points)
    const { data: trends, error: trendsError } = await supabase
      .from('analytics_trends')
      .select('*')
      .eq('user_id', userId)
      .order('timestamp', { ascending: false })
      .limit(30);

    if (trendsError) {
      logger.error('Error fetching trends:', trendsError);
    }

    // Get recent analyses
    const { data: recentAnalyses, error: analysesError } = await supabase
      .from('resume_analyses')
      .select(`
        id,
        job_role,
        analysis_type,
        file_name,
        ats_score,
        created_at
      `)
      .eq('user_id', userId)
      .order('created_at', { ascending: false })
      .limit(10);

    if (analysesError) {
      logger.error('Error fetching recent analyses:', analysesError);
    }

    return {
      analytics: analytics || {
        ats_score: 0,
        previous_ats_score: 0,
        overall_score: 0,
        skills_matched: 0,
        total_skills: 0,
        readability_score: 0,
        keyword_density: 0,
        total_analyses: 0,
      },
      trends: trends || [],
      recentAnalyses: recentAnalyses || [],
    };

  } catch (error) {
    logger.error('Error fetching user analytics:', error);
    throw error;
  }
};

/**
 * Generate analytics insights for user
 */
export const generateAnalyticsInsights = async (userId: string) => {
  try {
    const analyticsData = await getUserAnalytics(userId);
    const { analytics, trends } = analyticsData;

    const insights = [];

    // ATS Score insights
    if (analytics.ats_score > analytics.previous_ats_score) {
      insights.push({
        type: 'improvement',
        category: 'ATS Score',
        message: `Your ATS score improved by ${(analytics.ats_score - analytics.previous_ats_score).toFixed(1)} points!`,
        impact: 'positive'
      });
    } else if (analytics.ats_score < analytics.previous_ats_score) {
      insights.push({
        type: 'decline',
        category: 'ATS Score',
        message: `Your ATS score decreased by ${(analytics.previous_ats_score - analytics.ats_score).toFixed(1)} points.`,
        impact: 'negative'
      });
    }

    // Trend analysis
    if (trends.length >= 3) {
      const recentTrends = trends.slice(0, 3);
      const avgRecentScore = recentTrends.reduce((sum, t) => sum + t.ats_score, 0) / recentTrends.length;
      const olderTrends = trends.slice(3, 6);

      if (olderTrends.length > 0) {
        const avgOlderScore = olderTrends.reduce((sum, t) => sum + t.ats_score, 0) / olderTrends.length;

        if (avgRecentScore > avgOlderScore + 5) {
          insights.push({
            type: 'trend',
            category: 'Progress',
            message: 'You\'re on an upward trend! Keep up the great work.',
            impact: 'positive'
          });
        }
      }
    }

    // Frequency insights
    if (analytics.total_analyses >= 5) {
      insights.push({
        type: 'milestone',
        category: 'Usage',
        message: `You've completed ${analytics.total_analyses} resume analyses. You're becoming a pro!`,
        impact: 'neutral'
      });
    }

    return insights;

  } catch (error) {
    logger.error('Error generating analytics insights:', error);
    return [];
  }
};

