import React from 'react';
import { motion } from 'framer-motion';
import { Lock, Crown, Sparkles, ArrowRight } from 'lucide-react';
import { Button } from '../ui/Button';
import { Card, CardContent } from '../ui/Card';
import { useSubscription } from '../../hooks/useSubscription';

interface PremiumFeatureGateProps {
  featureName: string;
  description: string;
  children: React.ReactNode;
  requiredFeature?: keyof import('../../types/subscription').SubscriptionFeatures;
  showPreview?: boolean;
  previewHeight?: string;
  className?: string;
}

export function PremiumFeatureGate({
  featureName,
  description,
  children,
  requiredFeature,
  showPreview = true,
  previewHeight = '200px',
  className = ''
}: PremiumFeatureGateProps) {
  const { isPremium, hasFeature, openPaymentModal } = useSubscription();

  // Check if user has access to this specific feature
  const hasAccess = isPremium && (!requiredFeature || hasFeature(requiredFeature));

  if (hasAccess) {
    return <>{children}</>;
  }

  return (
    <div className={`relative ${className}`}>
      {/* Blurred Preview */}
      {showPreview && (
        <div 
          className="relative overflow-hidden rounded-lg"
          style={{ height: previewHeight }}
        >
          <div className="absolute inset-0 scale-110 filter blur-sm opacity-30 pointer-events-none">
            {children}
          </div>
          <div className="absolute inset-0 bg-gradient-to-t from-white via-white/80 to-transparent"></div>
        </div>
      )}

      {/* Premium Gate Overlay */}
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.5 }}
        className={`${showPreview ? 'absolute inset-0' : ''} flex items-center justify-center`}
      >
        <Card className="w-full max-w-md mx-auto shadow-xl border-2 border-gradient-to-r from-blue-500 to-purple-600">
          <CardContent className="p-6 text-center">
            <div className="bg-gradient-to-r from-blue-100 to-purple-100 p-4 rounded-full w-fit mx-auto mb-4">
              <Crown className="w-8 h-8 text-blue-600" />
            </div>

            <h3 className="font-bold text-xl text-gray-900 mb-2 flex items-center justify-center">
              <Lock className="w-5 h-5 mr-2 text-gray-500" />
              {featureName}
            </h3>

            <p className="text-gray-600 mb-6">
              {description}
            </p>

            <div className="bg-gradient-to-r from-blue-50 to-purple-50 p-4 rounded-lg mb-6">
              <div className="flex items-center justify-center mb-2">
                <Sparkles className="w-5 h-5 text-yellow-500 mr-2" />
                <span className="font-semibold text-gray-800">Premium Feature</span>
              </div>
              <p className="text-sm text-gray-600">
                Unlock this feature and many more with Premium access
              </p>
            </div>

            <Button 
              onClick={() => openPaymentModal('yearly')}
              className="w-full bg-gradient-to-r from-blue-600 to-purple-600 hover:from-blue-700 hover:to-purple-700 text-white font-semibold py-3 rounded-lg shadow-lg hover:shadow-xl transition-all duration-300"
            >
              <Crown className="w-4 h-4 mr-2" />
              Upgrade to Premium
              <ArrowRight className="w-4 h-4 ml-2" />
            </Button>            <p className="text-xs text-gray-500 mt-3">
              All sales are final
            </p>
          </CardContent>
        </Card>
      </motion.div>
    </div>
  );
}

export default PremiumFeatureGate;

src/pages/AuthCallback.tsx.content:
import { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { supabase } from '../utils/supabaseClient';
import { LoadingSpinner } from '../components/ui/LoadingSpinner';
import { diagnoseOAuthError, logEnvironmentInfo } from '../utils/oauth-error-diagnostics';

export default function AuthCallback() {
  const navigate = useNavigate();
  const [isProcessing, setIsProcessing] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Log any existing state values before processing
  console.log('⭐ Auth Callback Page Loaded');
  console.log('🔑 Stored state:', localStorage.getItem('supabase-auth-state'));
  console.log('📝 Session state:', sessionStorage.getItem('supabase-auth-state'));
  console.log('⏱️ OAuth initiated at:', sessionStorage.getItem('oauth-initiated-at'));

  useEffect(() => {
    const handleAuthCallback = async () => {      try {
        setIsProcessing(true);
        setError(null);

        console.log('🔄 Processing authentication callback...');
        console.log('🌐 Current URL:', window.location.href);
        console.log('🏠 Origin:', window.location.origin);

        // Add enhanced OAuth diagnostic logging
        logEnvironmentInfo();

        // Check for authentication fragments in both URL and hash (OAuth callback)
        const urlParams = new URLSearchParams(window.location.search);
        const hashParams = new URLSearchParams(window.location.hash.substring(1));

        // Debug all parameters to help troubleshoot
        console.log('📝 URL Parameters:', Object.fromEntries(urlParams.entries()));
        console.log('📝 Hash Parameters:', Object.fromEntries(hashParams.entries()));

        // Check if this is an OAuth callback with access_token
        const accessToken = hashParams.get('access_token') || urlParams.get('access_token');
        const refreshToken = hashParams.get('refresh_token') || urlParams.get('refresh_token');
        const error_description = hashParams.get('error_description') || urlParams.get('error_description') || hashParams.get('error') || urlParams.get('error');
        const provider = hashParams.get('provider') || urlParams.get('provider');

        console.log('🔑 Access token present:', !!accessToken);
        console.log('🔄 Refresh token present:', !!refreshToken);
        console.log('🔌 Provider:', provider || 'unknown');
        console.log('❌ Error description:', error_description);
          // First check for errors with enhanced diagnostics
        if (error_description) {
          console.error('❌ OAuth error:', error_description);

          // Run diagnostics for better error insights
          const errorDiagnosis = diagnoseOAuthError(urlParams, hashParams);
          console.log('🔍 OAuth Error Diagnosis:', errorDiagnosis);

          // Show more helpful error message with potential solution
          if (urlParams.get('error_code') === 'bad_oauth_state') {
            setError(`Authentication failed: OAuth state mismatch. This might be due to a port mismatch between 3000 and ${window.location.port}. Try using the run-auth-fixed-port.js script.`);
          } else {
            setError(`Authentication failed: ${error_description}`);
          }

          setTimeout(() => navigate('/login'), 5000); // Give more time to read the error
          return;
        }// State parameter check for CSRF protection with enhanced handling
        const expectedState = localStorage.getItem('supabase-auth-state');
        const sessionState = sessionStorage.getItem('supabase-auth-state');
        const returnedState = hashParams.get('state') || urlParams.get('state');
        const currentPort = window.location.port || '3000';

        console.log('🔒 Auth State Check:', { 
          expectedState, 
          sessionState, 
          returnedState,
          currentPort,
          currentUrl: window.location.href
        });

        // Enhanced state validation with better logging
        if (returnedState) {
          if (expectedState === returnedState || sessionState === returnedState) {
            console.log('✅ State validation passed');
          } else if (expectedState && returnedState && expectedState !== returnedState) {
            console.warn('⚠️ State mismatch detected');
            console.log('Expected state:', expectedState);
            console.log('Session state:', sessionState);
            console.log('Returned state:', returnedState);

            // Special handling for port-related mismatches (common in local development)
            const portInfoRegex = /_port(\d+)$/;
            const expectedPortMatch = expectedState?.match(portInfoRegex);
            const returnedPortMatch = returnedState?.match(portInfoRegex);

            if (expectedPortMatch && returnedPortMatch) {
              console.log(`Expected port: ${expectedPortMatch[1]}, Returned port: ${returnedPortMatch[1]}`);
              if (expectedPortMatch[1] !== returnedPortMatch[1]) {
                console.warn(`Port mismatch detected: expected ${expectedPortMatch[1]} but got ${returnedPortMatch[1]}`);
              }
            }

            // Clear the stale state but continue with authentication
            localStorage.removeItem('supabase-auth-state');
            sessionStorage.removeItem('supabase-auth-state');

            console.log('Proceeding with authentication despite state mismatch (for usability)');
          } else {
            console.log('No state comparison possible - missing expected state');
          }
        } else {
          console.log('No state returned from OAuth provider');
        }// Clean up stored state values to prevent future conflicts
        localStorage.removeItem('supabase-auth-state');
        sessionStorage.removeItem('supabase-auth-state');

        // Check for code in URL (used in PKCE flow)
        const code = urlParams.get('code');
        if (code) {
          console.log('🔑 Authorization code present, exchanging for tokens...');
          // Let Supabase handle the code exchange via handleRedirectResult
          const { data, error } = await supabase.auth.exchangeCodeForSession(code);

          if (error) {
            console.error('❌ Code exchange error:', error);
            setError(`Authentication failed: ${error.message}`);
            setTimeout(() => navigate('/login'), 3000);
            return;
          }

          if (data.session) {
            console.log('✅ Code exchange successful, session established');
            console.log('👤 User:', data.session.user?.email);

            // Clear the URL for security
            window.history.replaceState({}, document.title, window.location.pathname);

            // Redirect to home page on successful authentication
            navigate('/');
            return;
          }
        }

        // Handle implicit flow with direct tokens
        if (accessToken) {
          console.log('🔐 Setting session with OAuth tokens...');
          // Set the session manually using the tokens
          const { data, error } = await supabase.auth.setSession({
            access_token: accessToken,
            refresh_token: refreshToken || ''
          });

          if (error) {
            console.error('❌ Session setting error:', error);
            setError(`Authentication failed: ${error.message}`);
            setTimeout(() => navigate('/login'), 3000);
            return;
          }

          if (data.session) {
            console.log('✅ Authentication successful, session established');
            console.log('👤 User:', data.session.user?.email);

            // Clear the URL fragments for security
            window.history.replaceState({}, document.title, window.location.pathname);

            // Redirect to home page on successful authentication
            navigate('/');
            return;
          }
        }

        // If no OAuth tokens in URL, try handleRedirectResult first
        console.log('📝 Attempting to handle redirect result...');
        try {
          const { error: redirectError } = await supabase.auth.getSession(); 
          if (redirectError) {
            console.warn('⚠️ Redirect handling produced an error:', redirectError);
            // Continue to next fallback
          } else {
            console.log('✅ Auth state updated successfully');
          }
        } catch (err) {
          console.error('❌ Error handling redirect:', err);
          // Continue to next fallback
        }

        // Final fallback: check for existing session
        const { data: { session }, error: sessionError } = await supabase.auth.getSession();

        if (sessionError) {
          console.error('❌ Session verification error:', sessionError);
          setError('Session verification failed.');
          setTimeout(() => navigate('/login'), 3000);
          return;
        }if (session) {
          console.log('Existing session found, redirecting to home');
          navigate('/');
        } else {
          console.log('No valid session found');
          setError('No valid session found. Please sign in again.');
          setTimeout(() => navigate('/login'), 3000);
        }
      } catch (error) {
        console.error('Unexpected error in auth callback:', error);
        setError('An unexpected authentication error occurred.');
        setTimeout(() => navigate('/login'), 3000);
      } finally {
        setIsProcessing(false);
      }
    };

    handleAuthCallback();
  }, [navigate]);
  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-50 dark:bg-gray-900">
      <div className="text-center">
        {isProcessing ? (
          <>
            <h2 className="text-2xl font-semibold text-gray-900 dark:text-white mb-4">
              Processing authentication...
            </h2>
            <LoadingSpinner />
          </>
        ) : error ? (
          <>
            <h2 className="text-2xl font-semibold text-red-600 dark:text-red-400 mb-4">
              Authentication Error
            </h2>
            <p className="text-gray-600 dark:text-gray-300 mb-4">{error}</p>
            <p className="text-sm text-gray-500 dark:text-gray-400">
              Redirecting to login page...
            </p>
          </>
        ) : (          <>
            <h2 className="text-2xl font-semibold text-green-600 dark:text-green-400 mb-4">
              Authentication Successful
            </h2>            <p className="text-gray-600 dark:text-gray-300">
              Redirecting to home page...
            </p>
          </>
        )}
      </div>
    </div>
  );
}

src/hooks/useAnalytics.ts.content:
import { useState, useEffect, useMemo } from 'react';
import { format } from 'date-fns';

interface AnalyticsData {
  dailyUploads: number[];
  weeklyScores: number[];
  popularJobRoles: { role: string; count: number }[];
  averageScore: number;
  totalUploads: number;
  dates: string[];
}

export function useAnalytics() {
  const [data, setData] = useState<AnalyticsData>({
    dailyUploads: [],
    weeklyScores: [],
    popularJobRoles: [],
    averageScore: 0,
    totalUploads: 0,
    dates: [],
  });
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    // Track data loading
    const startTime = performance.now();
    setIsLoading(true);

    // Use a more efficient approach to generate mock data
    const fetchAnalyticsData = async () => {
      try {
        // Simulate network delay - in a real app, this would be an API call
        // Using a shorter timeout for better UX
        await new Promise(resolve => setTimeout(resolve, 300));

        // Generate dates once and cache them
        const now = new Date();
        const dates = Array.from({ length: 7 }, (_, i) => {
          const date = new Date(now);
          date.setDate(date.getDate() - i);
          return format(date, 'MMM dd');
        }).reverse();

        // Generate data in a single pass where possible
        const dailyUploads = Array.from({ length: 7 }, () => 
          Math.floor(Math.random() * 50) + 10
        );

        const weeklyScores = Array.from({ length: 7 }, () => 
          Math.floor(Math.random() * 30) + 70
        );

        // Compute this once rather than sorting on each render
        const popularJobRoles = [
          { role: 'Software Engineer', count: Math.floor(Math.random() * 100) + 50 },
          { role: 'Data Scientist', count: Math.floor(Math.random() * 80) + 40 },
          { role: 'Product Manager', count: Math.floor(Math.random() * 60) + 30 },
          { role: 'UX Designer', count: Math.floor(Math.random() * 40) + 20 },
          { role: 'Marketing Manager', count: Math.floor(Math.random() * 30) + 10 },
        ].sort((a, b) => b.count - a.count);

        // Calculate these once
        const totalUploads = dailyUploads.reduce((acc, curr) => acc + curr, 0);
        const averageScore = Math.floor(
          weeklyScores.reduce((acc, curr) => acc + curr, 0) / weeklyScores.length
        );

        setData({
          dailyUploads,
          weeklyScores,
          popularJobRoles,
          averageScore,
          totalUploads,
          dates,
        });

        // Log performance
        const endTime = performance.now();
        console.log(`Analytics data generated in ${endTime - startTime}ms`);
      } catch (error) {
        console.error('Error generating analytics data:', error);
      } finally {
        setIsLoading(false);
      }
    };

    fetchAnalyticsData();

    // Reduced update frequency to improve performance
    // Only update data every 5 minutes instead of every minute
    const interval = setInterval(fetchAnalyticsData, 300000);

    return () => clearInterval(interval);
  }, []);

  // Memoize derived data to prevent recalculation
  const derivedData = useMemo(() => {
    // Calculate any additional metrics here that depend on the base data
    const trendsPositive = data.weeklyScores[data.weeklyScores.length - 1] > 
                           data.weeklyScores[0];

    const topJobRole = data.popularJobRoles.length > 0 ? 
                      data.popularJobRoles[0].role : 
                      'None';

    return {
      trendsPositive,
      topJobRole,
      // Additional metrics can be added here
    };
  }, [data.weeklyScores, data.popularJobRoles]);

  return {
    ...data,
    ...derivedData,
    isLoading
  };
}

src/components/ui/LoadingSpinner.tsx.content:
/**
 * Enhanced Loading Spinner Component with multiple variants
 * Provides modern loading states for better UX
 */

import React from 'react';
import { motion } from 'framer-motion';
import { Loader2, Circle, RotateCw } from 'lucide-react';

interface LoadingSpinnerProps {
  size?: 'sm' | 'md' | 'lg' | 'xl';
  variant?: 'default' | 'dots' | 'pulse' | 'wave' | 'gradient';
  color?: 'blue' | 'indigo' | 'purple' | 'green' | 'amber' | 'red';
  text?: string;
  className?: string;
}

export function LoadingSpinner({ 
  size = 'md', 
  variant = 'default', 
  color = 'blue',
  text,
  className = ''
}: LoadingSpinnerProps) {
  const sizeClasses = {
    sm: 'w-4 h-4',
    md: 'w-6 h-6',
    lg: 'w-8 h-8',
    xl: 'w-12 h-12'
  };

  const colorClasses = {
    blue: 'text-blue-600 dark:text-blue-400',
    indigo: 'text-indigo-600 dark:text-indigo-400',
    purple: 'text-purple-600 dark:text-purple-400',
    green: 'text-green-600 dark:text-green-400',
    amber: 'text-amber-600 dark:text-amber-400',
    red: 'text-red-600 dark:text-red-400'
  };

  const renderSpinner = () => {
    switch (variant) {
      case 'dots':
        return (
          <div className="flex space-x-1">
            {[0, 1, 2].map((i) => (
              <motion.div
                key={i}
                className={`w-2 h-2 rounded-full bg-current ${colorClasses[color]}`}
                animate={{
                  scale: [1, 1.2, 1],
                  opacity: [0.5, 1, 0.5]
                }}
                transition={{
                  duration: 1.2,
                  repeat: Infinity,
                  delay: i * 0.2
                }}
              />
            ))}
          </div>
        );

      case 'pulse':
        return (
          <motion.div
            className={`rounded-full border-2 border-current ${sizeClasses[size]} ${colorClasses[color]}`}
            animate={{
              scale: [1, 1.2, 1],
              opacity: [0.7, 1, 0.7]
            }}
            transition={{
              duration: 1.5,
              repeat: Infinity,
              ease: "easeInOut"
            }}
          />
        );

      case 'wave':
        return (
          <div className="flex space-x-1">
            {[0, 1, 2, 3, 4].map((i) => (
              <motion.div
                key={i}
                className={`w-1 bg-current ${colorClasses[color]}`}
                style={{ height: '20px' }}
                animate={{
                  scaleY: [0.4, 1, 0.4]
                }}
                transition={{
                  duration: 1,
                  repeat: Infinity,
                  delay: i * 0.1
                }}
              />
            ))}
          </div>
        );

      case 'gradient':
        return (
          <motion.div
            className={`${sizeClasses[size]} rounded-full`}
            style={{
              background: `conic-gradient(from 0deg, transparent, currentColor)`,
            }}
            animate={{ rotate: 360 }}
            transition={{
              duration: 1,
              repeat: Infinity,
              ease: "linear"
            }}
          />
        );

      default:
        return (
          <Loader2 
            className={`animate-spin ${sizeClasses[size]} ${colorClasses[color]}`}
          />
        );
    }
  };

  return (
    <div className={`flex flex-col items-center justify-center space-y-2 ${className}`}>
      {renderSpinner()}
      {text && (
        <motion.p
          className={`text-sm font-medium ${colorClasses[color]}`}
          animate={{ opacity: [0.5, 1, 0.5] }}
          transition={{ duration: 2, repeat: Infinity }}
        >
          {text}
        </motion.p>
      )}
    </div>
  );
}

// Skeleton Loader Component for content placeholders
export function SkeletonLoader({ 
  lines = 3, 
  className = '',
  animated = true 
}: { 
  lines?: number; 
  className?: string;
  animated?: boolean;
}) {
  return (
    <div className={`space-y-3 ${className}`}>
      {Array.from({ length: lines }).map((_, i) => (
        <motion.div
          key={i}
          className={`h-4 bg-gray-200 dark:bg-gray-700 rounded ${
            i === lines - 1 ? 'w-3/4' : 'w-full'
          }`}
          animate={animated ? {
            opacity: [0.5, 1, 0.5]
          } : {}}
          transition={animated ? {
            duration: 1.5,
            repeat: Infinity,
            delay: i * 0.1
          } : {}}
        />
      ))}
    </div>
  );
}

// Card Skeleton for loading cards
export function CardSkeleton({ className = '' }: { className?: string }) {
  return (
    <div className={`p-6 border border-gray-200 dark:border-gray-700 rounded-lg ${className}`}>
      <div className="flex items-start space-x-4">
        <div className="w-12 h-12 bg-gray-200 dark:bg-gray-700 rounded-lg animate-pulse" />
        <div className="flex-1 space-y-2">
          <div className="h-4 bg-gray-200 dark:bg-gray-700 rounded w-3/4 animate-pulse" />
          <div className="h-3 bg-gray-200 dark:bg-gray-700 rounded w-1/2 animate-pulse" />
        </div>
      </div>
      <div className="mt-4 space-y-2">
        <div className="h-3 bg-gray-200 dark:bg-gray-700 rounded w-full animate-pulse" />
        <div className="h-3 bg-gray-200 dark:bg-gray-700 rounded w-5/6 animate-pulse" />
      </div>
    </div>
  );
}

