import React from 'react';
import { cva, type VariantProps } from 'class-variance-authority';
import { cn } from '../../utils/cn';

const badgeVariants = cva(
  'inline-flex items-center rounded-full border px-2.5 py-0.5 text-xs font-medium tracking-wide transition-colors focus:outline-none focus:ring-2 focus:ring-offset-2 shadow-sm',
  {
    variants: {
      variant: {
        default: 'border-brand-200 bg-brand-50 text-brand-700 dark:bg-brand-900/30 dark:text-brand-300 dark:border-brand-800/30 dark:shadow-brand-500/10',
        secondary: 'border-gray-200 bg-gray-50 text-gray-700 dark:bg-gray-800/80 dark:text-gray-200 dark:border-gray-700/40 backdrop-blur-sm',
        success: 'border-green-200 bg-green-50 text-green-700 dark:bg-green-900/30 dark:text-green-300 dark:border-green-800/30 dark:shadow-green-500/10',
        warning: 'border-amber-200 bg-amber-50 text-amber-700 dark:bg-amber-900/30 dark:text-amber-300 dark:border-amber-800/30 dark:shadow-amber-500/10',
        error: 'border-red-200 bg-red-50 text-red-700 dark:bg-red-900/30 dark:text-red-300 dark:border-red-800/30 dark:shadow-red-500/10',
        outline: 'text-gray-700 border-gray-300 dark:text-neutral-100 dark:border-gray-700',
        premium: 'border-premium-200 bg-gradient-gold text-white dark:border-premium-700/50 shadow-premium-sm',
        brand: 'border-brand-200 bg-gradient-brand text-white dark:border-brand-700/50 shadow-button-sm',
      },
    },
    defaultVariants: {
      variant: 'default',
    },
  }
);

export interface BadgeProps
  extends React.HTMLAttributes<HTMLDivElement>,
    VariantProps<typeof badgeVariants> {}

function Badge({ className, variant, ...props }: BadgeProps) {
  return (
    <div className={cn(badgeVariants({ variant }), className)} {...props} />
  );
}

export { Badge, badgeVariants };

