import { useState, useEffect } from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { Button } from '../ui/Button';
import { MenuIcon, X, FileText, Sun, Moon, LogOut, BarChart3, User } from 'lucide-react';
import { useTheme } from '../../context/ThemeContext';
import { useAuth } from '../../hooks/useAuth';

export function HeaderWithAuth() {
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);
  const [mounted, setMounted] = useState(false);
  const { darkMode, toggleDarkMode } = useTheme();
  const { user, signOut, profile } = useAuth();
  const location = useLocation();
  const navigate = useNavigate();

  // Helper function to get user display name
  const getUserDisplayName = () => {
    if (!user) return 'User';

    // Try to get full name from user metadata (OAuth users)
    const fullName = user.user_metadata?.full_name || user.user_metadata?.name;
    if (fullName) {
      return fullName;
    }

    // Try to get name from profile
    if (profile?.name) {
      return profile.name;
    }

    // Fallback to email prefix
    return user.email?.split('@')[0] || 'User';
  };

  // Helper function to get user initials for avatar
  const getUserInitials = () => {
    const displayName = getUserDisplayName();
    if (displayName === 'User' || displayName === user?.email?.split('@')[0]) {
      // If using email fallback, use first letter of email
      return user?.email?.charAt(0).toUpperCase() || 'U';
    }

    // Use initials from actual name
    const names = displayName.split(' ');
    if (names.length >= 2) {
      return (names[0].charAt(0) + names[names.length - 1].charAt(0)).toUpperCase();
    }
    return displayName.charAt(0).toUpperCase();
  };

  const toggleMenu = () => {
    setIsMenuOpen(!isMenuOpen);
  };

  const handleLogout = async () => {
    await signOut();
    navigate('/');
  };

  useEffect(() => {
    // Set mounted to true after component mounts
    setMounted(true);

    const handleScroll = () => {
      if (window.scrollY > 10) {
        setScrolled(true);
      } else {
        setScrolled(false);
      }
    };

    // Check scroll position immediately on mount
    handleScroll();

    window.addEventListener('scroll', handleScroll);
    return () => {
      window.removeEventListener('scroll', handleScroll);
    };
  }, []);
  useEffect(() => {
    // Close menu when route changes
    setIsMenuOpen(false);
  }, [location]);
