/**
 * Enhanced setup-pdf-worker.js - More robust version for Vercel deployment
 * This script ensures the PDF.js worker files are properly set up in the public directory
 */

import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import { dirname } from 'path';
import { createRequire } from 'module';

// Enhanced error handling and logging
const logInfo = (message) => console.log(`[PDF-Worker] INFO: ${message}`);
const logWarning = (message) => console.warn(`[PDF-Worker] WARNING: ${message}`);
const logError = (message) => console.error(`[PDF-Worker] ERROR: ${message}`);
const logSuccess = (message) => console.log(`[PDF-Worker] SUCCESS: ${message}`);

try {
  const __filename = fileURLToPath(import.meta.url);
  const __dirname = dirname(__filename);
  const require = createRequire(import.meta.url);

  logInfo('Starting PDF worker setup...');

  // Safely load package.json
  let packageJson;
  try {
    packageJson = require('../package.json');
    logInfo('Successfully loaded package.json');
  } catch (err) {
    logError(`Failed to load package.json: ${err.message}`);
    logInfo('Attempting to read package.json directly as fallback');
    const packageJsonPath = path.resolve(__dirname, '../package.json');
    if (fs.existsSync(packageJsonPath)) {
      packageJson = JSON.parse(fs.readFileSync(packageJsonPath, 'utf8'));
      logInfo('Successfully loaded package.json using direct file read');
    } else {
      throw new Error('Cannot locate package.json');
    }
  }

  // Get PDF.js version
  const pdfjsVersion = packageJson.dependencies['pdfjs-dist']?.replace('^', '') || '5.2.133';
  logInfo(`Setting up PDF.js worker files for version ${pdfjsVersion}...`);

  // Setup directories
  const sourceDir = path.resolve(__dirname, '../node_modules/pdfjs-dist/build');
  const targetDir = path.resolve(__dirname, '../public/pdf-worker');

  logInfo(`Source directory: ${sourceDir}`);
  logInfo(`Target directory: ${targetDir}`);

  // Check if source directory exists
  if (!fs.existsSync(sourceDir)) {
    logError(`Source directory not found: ${sourceDir}`);
    logInfo('Checking alternative source paths...');

    const altSourceDirs = [
      path.resolve(__dirname, '../node_modules/pdfjs-dist/legacy/build'),
      path.resolve(__dirname, '../node_modules/pdfjs-dist/es5/build')
    ];

    for (const altDir of altSourceDirs) {
      if (fs.existsSync(altDir)) {
        logInfo(`Found alternative source directory: ${altDir}`);
        sourceDir = altDir;
        break;
      }
    }

    if (!fs.existsSync(sourceDir)) {
      throw new Error(`Cannot find PDF.js source directory. Make sure pdfjs-dist is installed correctly.`);
    }
  }

  // Create target directory if it doesn't exist
  if (!fs.existsSync(targetDir)) {
    logInfo(`Creating target directory: ${targetDir}`);
    fs.mkdirSync(targetDir, { recursive: true });
    logSuccess(`Created directory: ${targetDir}`);
  }

  // Files to copy - try different file extensions based on version
  const possibleWorkerFiles = [
    'pdf.worker.mjs',
    'pdf.worker.js',
    'pdf.worker.min.js'
  ];

  // Find available worker files
  const availableFiles = [];
  possibleWorkerFiles.forEach(file => {
    const sourcePath = path.join(sourceDir, file);
    if (fs.existsSync(sourcePath)) {
      availableFiles.push(file);
      if (file.endsWith('.map')) {
        const mapFile = `${file}.map`;
        const mapSourcePath = path.join(sourceDir, mapFile);
        if (fs.existsSync(mapSourcePath)) {
          availableFiles.push(mapFile);
        }
      }
    }
  });

  if (availableFiles.length === 0) {
    logError('No PDF worker files found. List of files in source directory:');
    try {
      const files = fs.readdirSync(sourceDir);
      files.forEach(file => logInfo(` - ${file}`));

      // If we find any pdf worker file with any name, copy it
      const pdfWorkerFile = files.find(file => file.includes('pdf.worker'));
      if (pdfWorkerFile) {
        logInfo(`Found alternative worker file: ${pdfWorkerFile}`);
        availableFiles.push(pdfWorkerFile);
      }
    } catch (err) {
      logError(`Failed to list directory: ${err.message}`);
    }
  }

  // Copy each available file
  let copiedFiles = 0;
  for (const file of availableFiles) {
    const sourcePath = path.join(sourceDir, file);
    const targetPath = path.join(targetDir, file);

    try {
      fs.copyFileSync(sourcePath, targetPath);
      logSuccess(`Copied ${file} to public/pdf-worker`);
      copiedFiles++;
    } catch (err) {
      logError(`Failed to copy ${file}: ${err.message}`);
    }
  }

  // Create fallback if no files were copied
  if (copiedFiles === 0) {
    logWarning('No files were copied. Creating a placeholder worker file.');
    const placeholderPath = path.join(targetDir, 'pdf.worker.js');
    fs.writeFileSync(placeholderPath, `
      // Fallback PDF worker file created during build
      // This is a placeholder and may cause PDF viewing issues
      self.onmessage = function(event) {
        self.postMessage({
          error: true,
          message: 'This is a fallback PDF worker. PDF viewing may not work correctly.'
        });
      };
    `);
    logInfo('Created placeholder worker file. PDFs may not render correctly.');
  }

  // Final summary
  logSuccess(`PDF worker setup complete. Copied ${copiedFiles} files.`);

} catch (error) {
  logError(`PDF worker setup failed: ${error.message}`);
  logError(error.stack);
  // Don't exit with error to allow build to continue
  logWarning('Continuing build process despite PDF worker setup failure.');
}

src/hooks/useJobMatching.ts.content:
import { useState } from 'react';
import { JobMatch } from '../types/jobs';
import { parseResumeForJobs } from '../services/jobs/resumeParseService';
import { fetchJobMatches } from '../services/jobs/jobMatchService';

interface UseJobMatchingResult {
  isModalOpen: boolean;
  openModal: () => void;
  closeModal: () => void;
  uploadAndFindJobs: (file: File) => Promise<void>;
  isLoading: boolean;
  error: string | null;
  resumeFile: File | null;
  matchedJobs: JobMatch[];
}

export function useJobMatching(): UseJobMatchingResult {
  const [isModalOpen, setIsModalOpen] = useState<boolean>(false);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [resumeFile, setResumeFile] = useState<File | null>(null);
  const [matchedJobs, setMatchedJobs] = useState<JobMatch[]>([]);

  const openModal = () => setIsModalOpen(true);
  const closeModal = () => setIsModalOpen(false);

  const uploadAndFindJobs = async (file: File) => {
    setIsLoading(true);
    setError(null);
    setResumeFile(file);

    try {
      // Parse the resume
      const parsedData = await parseResumeForJobs(file);

      // Fetch matching jobs
      const jobs = await fetchJobMatches(parsedData);
      setMatchedJobs(jobs);

      // Open the modal to display results
      openModal();
    } catch (err) {
      console.error('Error in job matching process:', err);
      setError(typeof err === 'string' ? err : 'Failed to process resume for job matching');
    } finally {
      setIsLoading(false);
    }
  };

  return {
    isModalOpen,
    openModal,
    closeModal,
    uploadAndFindJobs,
    isLoading,
    error,
    resumeFile,
    matchedJobs
  };
}

src/components/auth/SignupModal.tsx.content:
import React, { useState, useEffect, memo } from 'react';
import { X, Github } from 'lucide-react';
import { Button } from '../ui/Button';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from '../ui/Dialog';
import { Input } from '../ui/Input';
import { SignUpModalProps } from './LoginModal.types';
import { useAuth } from '../../hooks/useAuth';
import { useToast } from '../../context/ToastContext';
import { useOAuthWithTimeout } from '../../hooks/useOAuthWithTimeout';

// Base component that we'll wrap with React.memo
function SignUpModalComponent({ isOpen, onClose, onLoginClick }: SignUpModalProps) {
  // Remove excessive logging that contributes to re-renders

  const [email, setEmail] = useState('checkresmueai@gmail.com'); // Default to the proper email
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [signupSuccess, setSignupSuccess] = useState(false);
  const { signUp } = useAuth();
  const { showToast } = useToast();
  const { 
    handleOAuthSignIn, 
    oauthLoading, 
    clearOAuthLoading  
  } = useOAuthWithTimeout();
    // Reset form when modal closes - using a ref to prevent unnecessary re-renders
  const isFirstRender = React.useRef(true);
  const isOpen_prev = React.useRef(isOpen);

  // Store clearOAuthLoading in a ref to avoid dependency issues
  const clearOAuthLoadingRef = React.useRef(clearOAuthLoading);

  // Update the ref when clearOAuthLoading changes
  React.useEffect(() => {
    clearOAuthLoadingRef.current = clearOAuthLoading;
  }, [clearOAuthLoading]);

  // Handle modal state changes with a stable effect
  useEffect(() => {
    // Skip the effect on first render
    if (isFirstRender.current) {
      isFirstRender.current = false;
      isOpen_prev.current = isOpen;
      return;
    }

    // Only process when isOpen changes from true to false
    if (isOpen_prev.current && !isOpen) {
      // Reset form state only when modal closes
      setEmail('checkresmueai@gmail.com');
      setPassword('');
      setConfirmPassword('');
      setError('');
      setIsLoading(false);

      // Use the ref to avoid dependency on clearOAuthLoading
      clearOAuthLoadingRef.current();
    }

    // Update previous value
    isOpen_prev.current = isOpen;
  }, [isOpen]);

  // Cleanup on component unmount - no dependencies needed
  useEffect(() => {
    return () => {
      // Use the ref instead of the function directly
      clearOAuthLoadingRef.current();
    };
  }, []);

  // Let Dialog handle visibility through its open prop

  // Add comprehensive form validation
  const validateForm = (): boolean => {
    if (!email || !password || !confirmPassword) {
      setError('Please fill in all fields');
      return false;
    }
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      setError('Please enter a valid email address');
      return false;
    }
    if (password.length < 6) {
      setError('Password must be at least 6 characters');
      return false;
    }
    if (password !== confirmPassword) {
      setError('Passwords do not match');
      return false;
    }
    return true;
  };  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    console.log('📝 [SignupModal] Form submission started');
    setError('');

    if (!validateForm()) {
      console.log('[SignupModal] Form validation failed');
      return;
    }

    setIsLoading(true);
    console.log('📧 [SignupModal] Starting enhanced email signup process');

    // Clear any existing timeout
    let timeoutId: NodeJS.Timeout | null = null;

    // Create timeout promise with better error handling
    const timeoutPromise = new Promise<never>((_, reject) => {
      timeoutId = setTimeout(() => {
        console.error('⏰ [SignupModal] Signup timeout reached (25s)');
        reject(new Error('Signup is taking longer than expected. Please check your connection and try again.'));
      }, 25000); // 25 seconds for signup as it might take longer
    });

    try {
      console.log('📧 [SignupModal] Attempting email signup...');

      // Race between signup and timeout
      const authPromise = signUp(email, password);
      const result = await Promise.race([authPromise, timeoutPromise]);

      // Clear timeout on completion
      if (timeoutId) {
        clearTimeout(timeoutId);
        timeoutId = null;
      }

      console.log('✅ [SignupModal] Signup result received:', { hasUser: !!result.user, hasError: !!result.error });

      if (result.error) {
        console.error('❌ [SignupModal] Signup error:', result.error.message);
        const errorMsg = getReadableErrorMessage(result.error.message);
        setError(errorMsg);
        showToast(errorMsg, 'error');
        return;
      }

      if (result.user) {
        console.log('🎉 [SignupModal] Signup successful');
        showToast('Successfully signed up! Please check your email to verify your account.', 'success');
        onClose();
      } else {
        console.warn('⚠️ [SignupModal] No user or error returned from signup');
        const errorMsg = 'Signup failed. Please try again.';
        setError(errorMsg);
        showToast(errorMsg, 'error');
      }
    } catch (error) {
      // Clean up timeout on error
      if (timeoutId) {
        clearTimeout(timeoutId);
        timeoutId = null;
      }

      console.error('💥 [SignupModal] Signup exception:', error);
      const errorMsg = error instanceof Error 
        ? getReadableErrorMessage(error.message)
        : 'An unexpected error occurred during signup. Please try again.';

      setError(errorMsg);
      showToast(errorMsg, 'error');
    } finally {
      console.log('🔄 [SignupModal] Clearing loading state');
      setIsLoading(false);

      // Final cleanup of timeout
      if (timeoutId) {
        clearTimeout(timeoutId);
      }
    }
  };

  // Helper function to convert technical error messages to user-friendly ones
  const getReadableErrorMessage = (errorMessage: string): string => {
    const message = errorMessage.toLowerCase();

    if (message.includes('user already registered') || message.includes('already exists')) {
      return 'An account with this email already exists. Please sign in instead.';
    }

    if (message.includes('password') && message.includes('weak')) {
      return 'Password is too weak. Please use at least 6 characters with a mix of letters and numbers.';
    }

    if (message.includes('invalid email') || message.includes('email format')) {
      return 'Please enter a valid email address.';
    }

    if (message.includes('rate limit') || message.includes('too many')) {
      return 'Too many attempts. Please wait a few minutes before trying again.';
    }

    if (message.includes('network') || message.includes('connection') || message.includes('timeout')) {
      return 'Connection issue. Please check your internet connection and try again.';
    }

    // Return original message if no pattern matches, but clean it up
    return errorMessage.charAt(0).toUpperCase() + errorMessage.slice(1);
  };// Enhanced OAuth sign in with proper error handling
  const handleOAuthSignInClick = async (provider: 'google' | 'github') => {
    console.log(`[SignupModal] OAuth signin initiated for ${provider}`);

    if (oauthLoading || isLoading) {
      console.log(`[SignupModal] OAuth signin blocked - already loading (oauthLoading: ${oauthLoading}, isLoading: ${isLoading})`);
      return;
    }

    setError('');

    // Use the hook's handleOAuthSignIn with error callback
    await handleOAuthSignIn(provider, (error: string) => {
      console.error(`[SignupModal] ${provider} sign-in error:`, error);
      setError(error);
    });

    // If we reach here, OAuth was successful and we should close the modal
    console.log(`[SignupModal] OAuth signin successful for ${provider}`);
    onClose();
  };
  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent 
        className="stable-modal"
        data-testid="signup-modal"
        style={{
          width: '448px',
          maxWidth: '90vw',
          minHeight: '500px',
