import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { CheckCircle, Circle, AlertCircle, TrendingUp, Clock, Loader2 } from 'lucide-react';
import '../../styles/progressBar.css';
import { cn } from '../../utils/cn';

interface Stage {
  id: string;
  name: string;
  progress: number;
  status: 'pending' | 'processing' | 'completed' | 'error';
}

interface ProgressBarProps {
  progress: number;
  showPercentage?: boolean;
  className?: string;
  stages?: Stage[];
}

export function ProgressBar({ 
  progress, 
  showPercentage = true, 
  className = '',
  stages 
}: ProgressBarProps) {
  const getStageIcon = (status: Stage['status']) => {
    switch (status) {
      case 'pending':
        return <Clock className="w-4 h-4 text-gray-400" />;
      case 'processing':
        return <Loader2 className="w-4 h-4 text-blue-500 animate-spin" />;
      case 'completed':
        return <CheckCircle className="w-4 h-4 text-green-500 mr-2" />;
      case 'error':
        return <AlertCircle className="w-4 h-4 text-red-500" />;
    }
  };

  return (
    <div className={`w-full ${className}`}>
      {stages ? (
        <div className="space-y-4">
          {stages.map((stage) => (
            <div key={stage.id} className="relative">
              <div className="flex items-center justify-between mb-1">
                <div className="flex items-center">
                  {getStageIcon(stage.status)}
                  <span className="text-sm font-medium text-gray-700 dark:text-gray-300">{stage.name}</span>
                </div>
                <span className="text-sm text-gray-500 dark:text-gray-400">{stage.status === 'error' ? 'Failed' : `${stage.progress}%`}</span>
              </div>
              <div className="h-3 bg-gray-100 dark:bg-gray-800/80 rounded-full overflow-hidden shadow-inner-light dark:shadow-inner-dark backdrop-blur-sm border border-gray-200/50 dark:border-gray-700/50">
                <motion.div
                  className={`h-full ${
                    stage.status === 'completed' 
                      ? 'bg-gradient-to-r from-green-400 to-green-500 shadow-lg shadow-green-500/20' 
                      : stage.status === 'processing' 
                        ? 'bg-gradient-brand shadow-lg shadow-brand-500/20 premium-shimmer' 
                        : 'bg-gray-300 dark:bg-gray-600'
                  }`}
                  initial={{ width: 0 }}
                  animate={{ width: `${stage.progress}%` }}
                  transition={{ duration: 0.5, ease: "easeInOut" }}
                />
              </div>
            </div>
          ))}
        </div>
      ) : (
        <div className="progress-bar relative">
          <div className="h-4 bg-gray-100 dark:bg-gray-800/80 rounded-full overflow-hidden shadow-inner-light dark:shadow-inner-dark backdrop-blur-sm border border-gray-200/50 dark:border-gray-700/50">
            <motion.div
              className="h-full bg-gradient-brand premium-shimmer shadow-lg shadow-brand-500/20"
              initial={{ width: 0 }}
              animate={{ width: `${progress}%` }}
              transition={{ 
                duration: 0.8, 
                ease: [0.34, 1.56, 0.64, 1], // Custom spring-like easing
                delay: 0.1 
              }}
            />
            <motion.div 
              className="absolute top-0 left-0 h-full pointer-events-none"
              style={{ width: `${progress}%` }}
              initial={{ opacity: 0 }}
              whileHover={{ opacity: 1 }}
            >
              <div className="absolute right-0 top-0 h-4 w-1.5 cursor-indicator progress-indicator"></div>
            </motion.div>
          </div>
          {showPercentage && (
            <div className="mt-1.5 flex justify-between items-center">
              <div className="progress-label flex items-center">
                <TrendingUp className="w-3.5 h-3.5 mr-1.5 text-blue-500" />
                <span className="text-xs text-gray-800 font-semibold">
                  {progress < 30 ? 'Needs Improvement' : progress < 70 ? 'Good Progress' : 'Excellent'}
                </span>
              </div>
              <span className="text-sm font-medium text-blue-600 dark:text-blue-400">{Math.round(progress)}%</span>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

src/utils/pdf-worker-manager.ts.content:
/**
 * PDF Worker Manager
 * 
 * Provides centralized management of PDF.js worker initialization and monitoring:
 * - Singleton pattern to prevent duplicate initialization
 * - Proper worker cleanup on errors
 * - Auto-recovery from known PDF.js errors
 * - Integration with callback store for reliable messaging
 */
import * as pdfjsLib from 'pdfjs-dist';
import { callbackStore } from './pdf-callback-store';
import { PdfWorkerConfig } from './pdf-worker.types';
import { initializeWorker } from './pdf-worker';

// Configuration constants
const MAX_RETRIES = 3;
const RETRY_DELAY_BASE = 1000; // Base delay in ms

// State management
class WorkerState {
  private static instance: WorkerState;
  private initializationRetries = 0;
  private isInitializing = false;
  private isInitialized = false;
  private initializationFailed = false;

  private constructor() {}

  static getInstance(): WorkerState {
    if (!WorkerState.instance) {
      WorkerState.instance = new WorkerState();
    }
    return WorkerState.instance;
  }

  reset(): void {
    this.initializationRetries = 0;
    this.isInitializing = false;
    this.isInitialized = false;
    this.initializationFailed = false;
  }

  incrementRetries(): number {
    return ++this.initializationRetries;
  }

  get retries(): number {
    return this.initializationRetries;
  }

  setInitializing(value: boolean): void {
    this.isInitializing = value;
  }

  get initializing(): boolean {
    return this.isInitializing;
  }

  setInitialized(value: boolean): void {
    this.isInitialized = value;
  }

  get initialized(): boolean {
    return this.isInitialized;
  }

  setFailed(value: boolean): void {
    this.initializationFailed = value;
  }

  get failed(): boolean {
    return this.initializationFailed;
  }
}

/**
 * Setup error handling for worker communication
 */
function setupErrorHandling(): () => void {
  const originalOnError = window.onerror;

  window.onerror = (message, source, lineno, colno, error) => {
    // Suppress expected worker communication errors
    if (message?.toString().includes('Receiving end does not exist')) {
      return true;
    }
    // Pass through other errors
    return originalOnError ? originalOnError(message, source, lineno, colno, error) : false;
  };

  // Return cleanup function
  return () => {
    window.onerror = originalOnError;
  };
}

/**
 * Reset global PDF.js state for clean retry
 */
async function resetPdfState(): Promise<void> {
  try {
    // Cleanup any existing worker
    if (pdfjsLib.GlobalWorkerOptions.workerPort) {
      pdfjsLib.GlobalWorkerOptions.workerPort.terminate();
    }

    // Reset worker options
    pdfjsLib.GlobalWorkerOptions.workerPort = null;
      // Clear callback store
    callbackStore.clear();

    // Allow garbage collection
    await new Promise(resolve => setTimeout(resolve, 100));
  } catch (error) {
    console.warn('Error during PDF state reset:', error);
  }
}

/**
 * Initialize the PDF worker with retry logic and proper state management
 */
export async function ensurePdfWorkerInitialized(config?: PdfWorkerConfig): Promise<boolean> {
  const state = WorkerState.getInstance();

  // Return immediately if already initialized
  if (state.initialized) {
    return true;
  }

  // Prevent concurrent initialization
  if (state.initializing) {
    await new Promise(resolve => setTimeout(resolve, 100));
    return state.initialized;
  }

  // Check if we've failed too many times
  if (state.failed || state.retries >= MAX_RETRIES) {
    console.error('Maximum PDF worker initialization retries reached');
    return false;
  }

  state.setInitializing(true);

  try {
    // Setup error handling
    const cleanupErrorHandler = setupErrorHandling();

    // Attempt initialization
    const workerConfig: PdfWorkerConfig = config || {
      workerSrc: '/pdf-worker/pdf.worker.min.mjs'
    };

    const success = await initializeWorker(workerConfig);

    if (success) {
      state.setInitialized(true);
      state.setInitializing(false);
      cleanupErrorHandler();
      return true;
    }

    throw new Error('Worker initialization failed');

  } catch (error) {
    console.warn(`PDF worker initialization attempt ${state.retries + 1} failed:`, error);

    state.incrementRetries();

    if (state.retries >= MAX_RETRIES) {
      state.setFailed(true);
      console.error('❌ PDF.js worker initialization failed after all attempts');
      return false;
    }

    // Reset state for retry
    await resetPdfState();

    // Wait with exponential backoff
    const retryDelay = RETRY_DELAY_BASE * Math.pow(2, state.retries - 1);
    await new Promise(resolve => setTimeout(resolve, retryDelay));

    // Recursive retry
    state.setInitializing(false);
    return ensurePdfWorkerInitialized(config);
  }
}

src/utils/subscriptionDebugTools.ts.content:
// Utility to check subscription status from the browser console
export function checkSubscriptionStatus() {
  console.log('Checking subscription status...');

  // Import necessary functions
  import('../context/subscriptionHelpers.ts')
    .then(({ getSubscriptionData, verifySubscriptionValidity }) => {
      // Get current user email (attempt to get from localStorage)
      let currentUserEmail = null;
      try {
        const storedUserData = localStorage.getItem('user_data');
        if (storedUserData) {
          const userData = JSON.parse(storedUserData);
          currentUserEmail = userData.email || null;
        }
      } catch (error) {
        console.error('Error getting user email:', error);
      }

      // Get current subscription from local storage
      const subscriptionData = getSubscriptionData();

      console.log('Current user email:', currentUserEmail);
      console.log('Current subscription data:', subscriptionData);

      // Validate the subscription
      const validatedSubscription = verifySubscriptionValidity(
        subscriptionData, 
        currentUserEmail
      );

      console.log('Validated subscription:', validatedSubscription);

      // Check if the subscription is valid
      const isPremium = validatedSubscription.tier !== 'free';
      const isOwner = currentUserEmail && 
                      validatedSubscription.subscriberEmail && 
                      validatedSubscription.subscriberEmail.toLowerCase() === currentUserEmail.toLowerCase();

      console.log('Is premium tier:', isPremium);
      console.log('Is subscription owner:', isOwner);

      // Check expiration status
      if (validatedSubscription.expiresAt) {
        const expiryDate = new Date(validatedSubscription.expiresAt);
        const now = new Date();
        const daysRemaining = Math.ceil((expiryDate.getTime() - now.getTime()) / (1000 * 60 * 60 * 24));

        console.log('Expiry date:', expiryDate.toLocaleDateString());
        console.log('Days remaining:', daysRemaining);
      }

      return {
        currentUserEmail,
        subscriptionData,
        validatedSubscription,
        isPremium,
        isOwner
      };
    })
    .catch(error => {
      console.error('Error checking subscription status:', error);
    });
}

