                            <div className="text-xs text-gray-500 dark:text-gray-400 mb-2">{template.category}</div>
                            {selectedTemplate === template.id && (
                              <button
                                onClick={(e) => {
                                  e.stopPropagation();
                                  if (isForExport) {
                                    handleTemplateSelect(template.id);
                                  } else {
                                    handleTemplateChange(template.id);
                                  }
                                }}
